package directories

import (
	"encoding/json"
	"os"
)

func List(directory string) ([]byte, error) {
	entries, err := os.ReadDir(directory)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, entry := range entries {
		names = append(names, entry.Name())
	}
	return json.Marshal(names)
}
